sys_script_include.script:
var KnowledgeLinkUtils = Class.create();
KnowledgeLinkUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    linkKnowledgeToInteraction: function() {
        var kbId = this.getParameter('sysparm_kb_id');
        var interactionId = this.getParameter('sysparm_interaction_id');

        var result = {
            success: false,
            message: ''
        };

        if (!kbId || !interactionId) {
            result.message = 'Missing KB ID or Interaction ID parameter.';
            return JSON.stringify(result);
        }

        // Query interaction to get the Number
        var interactionNum = '';
        var intGr = new GlideRecord('interaction');
        if (intGr.get(interactionId)) {
            interactionNum = intGr.getValue('number');
        } else {
            result.message = 'Interaction record not found.';
            return JSON.stringify(result);
        }

        // Query kb_knowledge to get Number, Version, Short Description
        var kbNum = '';
        var kbVersion = '';
        var kbShortDesc = '';

        var kbGr = new GlideRecord('kb_knowledge');
        if (kbGr.get(kbId)) {
            kbNum = kbGr.getValue('number');
            kbVersion = kbGr.getValue('version') || '1.0';
            kbShortDesc = kbGr.getValue('short_description') || '';
        } else {
            result.message = 'Knowledge Article not found.';
            return JSON.stringify(result);
        }

        // Overview formatting: 'Interaction: [Number], KB: [Number], Version: [Version], Name: [Short Description]'
        var overviewStr = 'Interaction: ' + interactionNum + ', KB: ' + kbNum + ', Version: ' + kbVersion + ', Name: ' + kbShortDesc;

        // Insert new record into x_snc_pab_ee_tkit_m2m_interaction_to_knowledge_link
        var m2mGr = new GlideRecord('x_snc_pab_ee_tkit_m2m_interaction_to_knowledge_link');
        m2mGr.initialize();
        m2mGr.setValue('interaction', interactionId);
        m2mGr.setValue('knowledge_article', kbId);
        m2mGr.setValue('overview', overviewStr);
        var sysId = m2mGr.insert();

        if (sysId) {
            result.success = true;
            result.message = 'Successfully linked Knowledge Article ' + kbNum + ' to Interaction ' + interactionNum + '.';
        } else {
            result.message = 'Failed to create association record.';
        }

        return JSON.stringify(result);
    },

    type: 'KnowledgeLinkUtils'
});
